begin;
insert into auth.users(id,email,raw_user_meta_data) values('00000000-0000-4000-8000-000000000011','calendar-test-1@example.invalid','{"full_name":"Calendar fixture"}'),('00000000-0000-4000-8000-000000000012','calendar-test-2@example.invalid','{"full_name":"Other fixture"}');
update public.profiles set status='active' where id in('00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000012');
insert into public.events(user_id,title,starts_at,ends_at) values('00000000-0000-4000-8000-000000000011','Visible','2026-11-06 15:00+01','2026-11-06 20:00+01'),('00000000-0000-4000-8000-000000000012','Invisible','2026-11-06 15:00+01','2026-11-06 20:00+01');
do $$declare feed jsonb; category uuid;begin
perform public.plania_calendar('create','00000000-0000-4000-8000-000000000011',jsonb_build_object('hash',repeat('a',64),'category_ids','[]'::jsonb));
feed:=public.plania_calendar('feed',null,jsonb_build_object('hash',repeat('a',64)));
if jsonb_array_length(feed->'events')<>1 or feed->'events'->0->>'title'<>'Visible' then raise exception 'FAIL isolation';end if;
update public.events set title='Edited' where user_id='00000000-0000-4000-8000-000000000011';
if public.plania_calendar('feed',null,jsonb_build_object('hash',repeat('a',64)))->'events'->0->>'title'<>'Edited' then raise exception 'FAIL edit';end if;
update public.events set deleted_at=now() where user_id='00000000-0000-4000-8000-000000000011';
if jsonb_array_length(public.plania_calendar('feed',null,jsonb_build_object('hash',repeat('a',64)))->'events')<>0 then raise exception 'FAIL deletion';end if;
update public.events set deleted_at=null,status='cancelled' where user_id='00000000-0000-4000-8000-000000000011';
if jsonb_array_length(public.plania_calendar('feed',null,jsonb_build_object('hash',repeat('a',64)))->'events')<>0 then raise exception 'FAIL cancellation';end if;
select id into category from public.categories where user_id='00000000-0000-4000-8000-000000000011' limit 1;
perform public.plania_calendar('create','00000000-0000-4000-8000-000000000011',jsonb_build_object('hash',repeat('b',64),'category_ids',jsonb_build_array(category)));
if public.plania_calendar('feed',null,jsonb_build_object('hash',repeat('a',64))) is not null then raise exception 'FAIL rotation';end if;
update public.events set status='planned' where user_id='00000000-0000-4000-8000-000000000011';
if jsonb_array_length(public.plania_calendar('feed',null,jsonb_build_object('hash',repeat('b',64)))->'events')<>0 then raise exception 'FAIL filter';end if;
update public.events set category_id=category where user_id='00000000-0000-4000-8000-000000000011';
if jsonb_array_length(public.plania_calendar('feed',null,jsonb_build_object('hash',repeat('b',64)))->'events')<>1 then raise exception 'FAIL selected category';end if;
update public.profiles set status='blocked' where id='00000000-0000-4000-8000-000000000011';
if public.plania_calendar('feed',null,jsonb_build_object('hash',repeat('b',64))) is not null then raise exception 'FAIL blocked';end if;
update public.profiles set status='active' where id='00000000-0000-4000-8000-000000000011';
perform public.plania_calendar('revoke','00000000-0000-4000-8000-000000000011');
if public.plania_calendar('feed',null,jsonb_build_object('hash',repeat('b',64))) is not null then raise exception 'FAIL revocation';end if;
end$$;
set local role anon;
do $$begin begin perform public.plania_calendar('status','00000000-0000-4000-8000-000000000011');raise exception 'FAIL anon access';exception when insufficient_privilege then null;end;end$$;
set local role authenticated;
do $$begin begin perform public.plania_calendar('status','00000000-0000-4000-8000-000000000011');raise exception 'FAIL client RPC access';exception when insufficient_privilege then null;end;end$$;
reset role;
